import{_ as e,o as t,c as n,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const _=JSON.parse('{"title":"Διαθεσιμότητα και κανάλια διασύνδεσης","description":"","frontmatter":{},"headers":[],"relativePath":"el/integrations/activation-and-channels.md","filePath":"el/integrations/activation-and-channels.md"}'),o={name:"el/integrations/activation-and-channels.md"};function l(r,a,s,c,d,h){return t(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="διαθεσιμοτητα-και-καναλια-διασυνδεσης" tabindex="-1">Διαθεσιμότητα και κανάλια διασύνδεσης <a class="header-anchor" href="#διαθεσιμοτητα-και-καναλια-διασυνδεσης" aria-label="Permalink to &quot;Διαθεσιμότητα και κανάλια διασύνδεσης&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Προσχέδιο βάσει πηγαίου κώδικα · v0.7.9. Επιβεβαιώστε διαθεσιμότητα και δικαιώματα στην εγκεκριμένη έκδοση.</p></div><h2 id="πριν-απο-τη-συνδεση-υπηρεσιας" tabindex="-1">Πριν από τη σύνδεση υπηρεσίας <a class="header-anchor" href="#πριν-απο-τη-συνδεση-υπηρεσιας" aria-label="Permalink to &quot;Πριν από τη σύνδεση υπηρεσίας&quot;">​</a></h2><ol><li>Επιβεβαιώστε την έκδοση, την εταιρεία και το κανάλι κρατήσεων.</li><li>Ελέγξτε την κατάσταση της διασύνδεσης και αν ο πάροχος έχει ρυθμιστεί και εγκριθεί.</li><li>Χρησιμοποιήστε συνθετικά στοιχεία σε εγκεκριμένο δοκιμαστικό περιβάλλον. Η δημόσια λήψη κρατήσεων και η αποστολή προς παρόχους παραμένουν απενεργοποιημένες μέχρι ξεχωριστή αποδοχή.</li><li>Ελέγξτε το αποτέλεσμα στον χώρο χειριστή. Η επιτυχής προεπισκόπηση δεν αποδεικνύει ζωντανή σύνδεση.</li></ol><h2 id="ερμηνεια-διαθεσιμοτητας" tabindex="-1">Ερμηνεία διαθεσιμότητας <a class="header-anchor" href="#ερμηνεια-διαθεσιμοτητας" aria-label="Permalink to &quot;Ερμηνεία διαθεσιμότητας&quot;">​</a></h2><p>Η υλοποίηση στον κώδικα, το sandbox και η ενεργή σύνδεση με πάροχο αποτελούν διαφορετικές καταστάσεις. Η ένδειξη <strong>Not configured</strong> αποκλείει πραγματικές εργασίες πελατών. Ένα ενεργό κανάλι δεν αποδεικνύει ενεργές πληρωμές ή αποστολή μηνυμάτων.</p><h2 id="αν-η-υπηρεσια-δεν-ειναι-διαθεσιμη" tabindex="-1">Αν η υπηρεσία δεν είναι διαθέσιμη <a class="header-anchor" href="#αν-η-υπηρεσια-δεν-ειναι-διαθεσιμη" aria-label="Permalink to &quot;Αν η υπηρεσία δεν είναι διαθέσιμη&quot;">​</a></h2><p>Ζητήστε από εξουσιοδοτημένο διαχειριστή να επιβεβαιώσει τις ρυθμίσεις και την ετοιμότητα της έκδοσης. Μην παρακάμπτετε απενεργοποιημένα στοιχεία ελέγχου και μη χρησιμοποιείτε διαπιστευτήρια άλλης εταιρείας.</p><p>Δείτε <a href="/el/plus/markets-and-locations.html">Αγορές και τοποθεσίες</a> και <a href="/el/developers/authentication.html">Πρόσβαση API</a>.</p>',9)])])}const m=e(o,[["render",l]]);export{_ as __pageData,m as default};
